-- Oracle-specific syntax: hierarchical queries, DUAL, flashback, sequences, special functions
SELECT employee_id, last_name, manager_id, LEVEL FROM employees START WITH manager_id IS NULL CONNECT BY PRIOR employee_id = manager_id;
SELECT LPAD(' ', 2 * (LEVEL - 1)) || last_name AS org_chart FROM employees START WITH manager_id IS NULL CONNECT BY PRIOR employee_id = manager_id ORDER SIBLINGS BY last_name;
SELECT employee_id, SYS_CONNECT_BY_PATH(last_name, '/') AS path FROM employees START WITH employee_id = 100 CONNECT BY PRIOR employee_id = manager_id;
SELECT last_name, CONNECT_BY_ROOT last_name AS root_name, CONNECT_BY_ISLEAF AS is_leaf FROM employees WHERE LEVEL > 1 START WITH manager_id IS NULL CONNECT BY PRIOR employee_id = manager_id;
SELECT employee_id FROM employees CONNECT BY NOCYCLE PRIOR employee_id = manager_id START WITH employee_id = 101;
SELECT LEVEL FROM dual CONNECT BY LEVEL <= 10;
SELECT TRUNC(SYSDATE) - LEVEL + 1 AS dt FROM dual CONNECT BY LEVEL <= 30;
SELECT TO_DATE('2024-01-01', 'YYYY-MM-DD') + LEVEL - 1 AS d FROM dual CONNECT BY LEVEL <= 366;
SELECT REGEXP_SUBSTR(:csv, '[^,]+', 1, LEVEL) AS token FROM dual CONNECT BY REGEXP_SUBSTR(:csv, '[^,]+', 1, LEVEL) IS NOT NULL;
SELECT employee_id, PRIOR last_name AS manager_name FROM employees CONNECT BY PRIOR employee_id = manager_id AND LEVEL <= 3 START WITH manager_id IS NULL;
SELECT SYSDATE FROM dual;
SELECT SYSTIMESTAMP, CURRENT_TIMESTAMP, LOCALTIMESTAMP, CURRENT_DATE FROM dual;
SELECT USER, SYS_CONTEXT('USERENV', 'SESSION_USER') AS su, SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA') AS cs FROM dual;
SELECT 1 FROM dual;
SELECT sys_guid() FROM dual;
SELECT customers_seq.NEXTVAL, customers_seq.CURRVAL FROM dual;
SELECT * FROM employees AS OF TIMESTAMP (SYSTIMESTAMP - INTERVAL '1' HOUR) WHERE employee_id = 100;
SELECT * FROM employees AS OF SCN 1234567 WHERE department_id = 10;
SELECT * FROM employees AS OF TIMESTAMP TO_TIMESTAMP('2024-06-01 10:00:00', 'YYYY-MM-DD HH24:MI:SS');
SELECT versions_starttime, versions_endtime, versions_operation, salary FROM employees VERSIONS BETWEEN TIMESTAMP SYSTIMESTAMP - INTERVAL '1' DAY AND SYSTIMESTAMP WHERE employee_id = 100;
FLASHBACK TABLE employees TO TIMESTAMP SYSTIMESTAMP - INTERVAL '15' MINUTE;
FLASHBACK TABLE orders TO BEFORE DROP;
SELECT ROWID, employee_id FROM employees WHERE ROWNUM = 1;
SELECT * FROM employees WHERE ROWID = :rid;
SELECT ORA_ROWSCN, employee_id FROM employees WHERE employee_id = 100;
SELECT employee_id, TO_CHAR(hire_date, 'DD-MON-YYYY') AS hired, TO_CHAR(salary, 'FM$999,999.00') AS sal, TO_NUMBER('1,234.50', '9,999.99') AS n FROM employees;
SELECT TO_CHAR(SYSDATE, 'Day, DD Month YYYY', 'NLS_DATE_LANGUAGE=ENGLISH') FROM dual;
SELECT MONTHS_BETWEEN(SYSDATE, hire_date) / 12 AS years, NEXT_DAY(SYSDATE, 'MONDAY') AS next_mon, EXTRACT(YEAR FROM hire_date) AS yr FROM employees;
SELECT CAST(salary AS VARCHAR2(20)) AS s, CAST(hire_date AS TIMESTAMP) AS ts, CAST(SYSTIMESTAMP AS DATE) FROM employees;
SELECT SUBSTR(last_name, 1, 3), INSTR(email, '@'), LENGTH(last_name), REPLACE(phone, '-', ''), TRIM(BOTH ' ' FROM name), LTRIM(name), RTRIM(name, '.'), INITCAP(name), TRANSLATE(name, 'abc', 'xyz') FROM customers;
SELECT NULLIF(a, b), GREATEST(a, b, c), LEAST(a, b, c), SIGN(x), MOD(x, 3), POWER(2, 10), CEIL(1.2), FLOOR(1.8), TRUNC(1.567, 2), ROUND(1.567, 1), ABS(-3) FROM t;
SELECT first_name || ' ' || last_name AS full_name FROM employees;
SELECT q'[It's quoted]' AS s, N'unicode' AS n FROM dual;
SELECT 'O''Brien' FROM dual;
SELECT 1.5E3, .5, 5., 1e-3 FROM dual;
SELECT INTERVAL '1-6' YEAR TO MONTH, INTERVAL '2 03:04:05' DAY TO SECOND FROM dual;
SELECT NUMTODSINTERVAL(5, 'MINUTE'), NUMTOYMINTERVAL(2, 'YEAR') FROM dual;
SELECT CAST(MULTISET(SELECT order_id FROM orders WHERE customer_id = c.customer_id) AS id_list_t) FROM customers c;
SELECT * FROM TABLE(my_pkg.get_rows(:p1));
SELECT * FROM TABLE(CAST(:coll AS number_tab_t));
SELECT column_value FROM TABLE(sys.odcinumberlist(1, 2, 3));
SELECT * FROM JSON_TABLE(:doc, '$.items[*]' COLUMNS (id NUMBER PATH '$.id', name VARCHAR2(100) PATH '$.name')) jt;
SELECT JSON_VALUE(payload, '$.user.name') AS uname, JSON_QUERY(payload, '$.tags') AS tags FROM events WHERE JSON_EXISTS(payload, '$.user');
SELECT JSON_OBJECT('id' VALUE employee_id, 'name' VALUE last_name) FROM employees;
SELECT JSON_ARRAYAGG(last_name ORDER BY last_name) FROM employees;
SELECT XMLELEMENT("emp", XMLATTRIBUTES(employee_id AS "id"), last_name) FROM employees;
SELECT * FROM XMLTABLE('/rows/row' PASSING XMLTYPE(:x) COLUMNS id NUMBER PATH 'id', nm VARCHAR2(50) PATH 'name');
SELECT /*+ INDEX(e idx_emp_dept) PARALLEL(4) */ employee_id FROM employees e WHERE department_id = 10;
SELECT /*+ FULL(o) NO_INDEX(o idx_orders_cust) */ COUNT(*) FROM orders o;
INSERT /*+ APPEND */ INTO sales_hist SELECT * FROM sales_staging;
SELECT * FROM employees SAMPLE (10);
SELECT * FROM employees PARTITION (p2024);
SELECT * FROM sales_hist PARTITION FOR (TO_DATE('2024-05-01', 'YYYY-MM-DD'));
SELECT * FROM remote_table@prod_link WHERE id = 1;
SELECT * FROM hr.employees e WHERE e.hire_date > SYSDATE - 7;
SELECT e.* FROM scott.emp e, scott.dept d WHERE e.deptno = d.deptno;
SELECT * FROM v$session WHERE username IS NOT NULL;
SELECT * FROM v$sql WHERE sql_text LIKE '%orders%';
SELECT table_name, num_rows FROM user_tables ORDER BY num_rows DESC NULLS LAST;
SELECT owner, segment_name, ROUND(SUM(bytes) / 1024 / 1024, 2) AS mb FROM dba_segments GROUP BY owner, segment_name ORDER BY mb DESC FETCH FIRST 20 ROWS ONLY;
SELECT column_name, data_type, data_length, nullable FROM all_tab_columns WHERE table_name = UPPER(:tbl) AND owner = :owner ORDER BY column_id;
SELECT constraint_name, constraint_type, search_condition FROM user_constraints WHERE table_name = 'ORDERS';
SELECT * FROM employees ORDER BY commission_pct DESC NULLS FIRST, last_name ASC NULLS LAST;
SELECT employee_id FROM employees WHERE commission_pct IS NOT NULL AND department_id NOT IN (10, 20, 30);
SELECT * FROM employees WHERE last_name LIKE 'S%' OR first_name LIKE '_a%';
SELECT * FROM employees WHERE salary * 12 > 100000 AND NOT (department_id = 10 OR department_id = 20);
SELECT -salary, +salary, salary - -1, 2 * (3 + 4) / 5 FROM employees;
SELECT DISTINCT job_id FROM employees;
SELECT UNIQUE job_id FROM employees;
SELECT ALL job_id FROM employees;
SELECT * FROM employees e1 WHERE salary = (SELECT MAX(salary) FROM employees e2 WHERE e2.department_id = e1.department_id);
SELECT * FROM (SELECT * FROM (SELECT * FROM (SELECT employee_id, salary FROM employees) WHERE salary > 1000) WHERE salary < 20000) WHERE ROWNUM < 5;
